// ====================================================================
// CHECK MEDIA API RESPONSE (register #4)
// Kirimi bisa balas HTTP 200 + body success:false -> node HTTP dianggap
// sukses padahal media TIDAK terkirim. Node ini meniru pola
// "Check API Response" jalur teks: throw kalau body menandakan gagal,
// error output -> Notify Admin Media Error.
// ====================================================================
const input = $input.first();
const r = input.json;

// Flag eksplisit false = gagal, apapun isi field lain
const explicitFail = r.success === false || r.status === false;

const isSuccess = !explicitFail && (
  r.status === true ||
  r.success === true ||
  (r.data && r.data.id) ||
  (r.message && r.message !== 'error')
);

if (!isSuccess) {
  console.log('X Kirimi MEDIA Response Error:', JSON.stringify(r));
  throw new Error('Kirimi media gagal (HTTP 200 + body gagal): ' + JSON.stringify(r).slice(0, 500));
}

return [input];
